<template><div class="calendar-page"><div class="head"><div><span>STUDIO SCHEDULE</span><h2>预约档期日历</h2><p>按日期查看拍摄安排和订单状态。</p></div><el-button @click="load" :loading="loading">刷新</el-button></div><div class="legend"><span>● 待确认</span><span>● 待付款 / 待拍摄</span><span>● 已付款待拍摄</span></div><el-calendar v-model="date"><template #date-cell="{data}"><div class="cell"><b>{{data.day.slice(-2)}}</b><div v-for="item in events[data.day]||[]" :key="item.id" class="event" @click="selected=item"><strong>{{item.slot}}</strong><small>{{item.photographer}} · {{item.status}}</small></div></div></template></el-calendar><el-dialog v-model="show" title="预约详情" width="420px"><p v-if="selected">摄影师：{{selected.photographer}}</p><p v-if="selected">客户：{{selected.customer}}</p><p v-if="selected">时间：{{selected.date}} {{selected.slot}}</p><p v-if="selected">状态：{{selected.status}}</p></el-dialog></div></template>
<script setup>
import {ref,computed,getCurrentInstance,onMounted,watch} from 'vue'
const ctx=getCurrentInstance().appContext.config.globalProperties,date=ref(new Date()),loading=ref(false),rows=ref([]),selected=ref(null)
const show=computed({get:()=>!!selected.value,set:v=>{if(!v)selected.value=null}})
const events=computed(()=>{const out={};rows.value.forEach(r=>{const d=String(r.yuyuesheyingriqi||'').slice(0,10);if(!d)return;const status=r.ispay==='已支付'?'已付款待拍摄':r.sfsh==='是'?'待付款 / 待拍摄':r.sfsh==='否'?'未通过':'待确认';(out[d]||(out[d]=[])).push({id:r.id,date:d,slot:r.yuyueshijianduan||'全天',photographer:r.sheyingxingming,customer:r.yonghuxingming||r.yonghuzhanghao,status})});return out})
async function load(){loading.value=true;try{const r=await ctx.$http.get('sheyingshiyuyue/page',{params:{page:1,limit:1000,sort:'yuyuesheyingriqi',order:'asc'}});rows.value=r.data.data.list||[]}finally{loading.value=false}} onMounted(load)
</script><style scoped>.calendar-page{padding:4px 0 28px}.head{display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:18px}.head span{font-size:11px;color:#82907f;letter-spacing:.15em}.head h2{margin:7px 0 4px;color:#294a3b}.head p{margin:0;color:#849083;font-size:13px}.legend{display:flex;gap:20px;margin:10px 0;color:#687568;font-size:12px}.cell{min-height:82px;padding:5px}.cell>b{font-size:12px;color:#738174}.event{margin-top:5px;padding:4px 6px;border-left:3px solid #4c9075;background:#eff8f3;border-radius:4px;cursor:pointer}.event strong,.event small{display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.event strong{font-size:10px}.event small{font-size:10px;color:#667568}.calendar-page :deep(.el-calendar-table .el-calendar-day){height:105px;padding:5px}@media(max-width:700px){.event small{display:none}.calendar-page :deep(.el-calendar-table .el-calendar-day){height:68px}.cell{min-height:55px}}
</style>
